// news-image-20261118 v2: writes the pre-rendered daily-briefing image to
// /output/entry.png. The image (a 1024x1024 PNG drawn offline) is embedded
// as base64 below; this program is stdlib-only and deterministic.
import { join } from "node:path";
import { mkdirSync, writeFileSync } from "node:fs";

const B64 = "";

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output";
const outFile = join(outDir, "entry.png");
mkdirSync(outDir, { recursive: true });
writeFileSync(outFile, Buffer.from(B64, "base64"));
